        shayariItem(1263, "एक अमीर ने पूछा 'मुल्ला दुनिया में अक्ल बड़ी या दौलत?'\nमुल्ला बोले 'दोनों बराबर हैं, पर अक्ल से दौलत कमाना है बड़ी नियामत!'", "मुल्ला नसरुद्दीन", catMulla, "दौलत"),
        shayariItem(1264, "नाव में बैठे पंडित जी ने पूछा 'मुल्ला व्याकरण जानते हो?'\nमुल्ला बोले 'नहीं!' पंडित बोले 'आधी ज़िंदगी बेकार गई मानते हो?'", "मुल्ला नसरुद्दीन", catMulla, "नाव"),
        shayariItem(1265, "नाव डूबने लगी तो मुल्ला बोले 'पंडित जी तैरना जानते हो?'\nपंडित बोले 'नहीं!' मुल्ला हँसे 'तब तो पूरी ज़िंदगी बेकार गई समझो!'", "मुल्ला नसरुद्दीन", catMulla, "तैरना"),
        shayariItem(1266, "मुल्ला ने कहा 'जो इंसान एक बार भी गलती न करे वो इंसान नहीं',\nऔर जो बार-बार एक ही गलती करे वो समझदार नहीं!", "मुल्ला नसरुद्दीन", catMulla, "गलती"),
        shayariItem(1267, "डॉक्टर ने पूछा 'मुल्ला जी क्या खाते हो जो इतने स्वस्थ हो?'\nमुल्ला बोले 'गुस्सा कम और हँसी ज़्यादा पीता हूँ, इसलिए मस्त हूँ!'", "मुल्ला नसरुद्दीन", catMulla, "सेहत"),
        shayariItem(1268, "भीड़ में किसी ने मुल्ला को धक्का दिया और माफ़ी न माँगी,\nमुल्ला मुस्कुराकर बोले 'भाई इतनी जल्दी किस बात की, आगे रास्ता खाली है!'", "मुल्ला नसरुद्दीन", catMulla, "धैर्य"),
        shayariItem(1269, "मुल्ला कहते हैं सस्ता रोए बार-बार, महंगा रोए एक बार,\nहँसकर जीने वाले हर दिन जिएँ हज़ार बार।", "मुल्ला नसरुद्दीन", catMulla, "जीवन मंत्र"),
        shayariItem(1270, "अक़्लमंदी और हँसी का मेल मुल्ला नसरुद्दीन से सीखिए,\nमुश्किल सवाल हो या मज़ाक, हर बात मुस्कुराकर लीजिए।", "मुल्ला नसरुद्दीन", catMulla, "मुस्कान")
    )
}
